window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q15"]=window.__LIBQ["the-gioi-hoan-my"]["q15"]||{};window.__LIBQ["the-gioi-hoan-my"]["q15"]["cotTruyen"]=[{"chuong":1401,"tieuDe":"Cò Kè Mặc Cả","tomTat":"Thạch Hạo kéo lão già tóc rối sang bên rồi dùng Lôi Trì tiếp tục truy bắt chùm sáng rơi khỏi dao cầu Trảm Tiên đài. Dị quang liên tục xuyên hư không, đổi hướng và phá thủng nhiều binh khí, trong đó có Kim bì hồ lô đi kèm Ngũ Sắc Thần Quang. Động tĩnh kinh động một vị vô địch bế quan tại tổ đàn, khiến bàn tay đen mang uy áp đáng sợ vươn ra giữa Đế quan. Mạnh Thiên Chính kịp thời xuất hiện, cầm cố thần mang rồi dùng Lôi Trì trấn áp nó, chấm dứt cuộc tranh đoạt trực tiếp. Các lão giả sau đó lần lượt đưa hắc ám Tiên kim, Tiên kim và Chí Tôn Pháp khí ra đề nghị đổi Lôi Trì, nhưng Thạch Hạo không chấp nhận. Hắn chuyển điều kiện sang thịt của năm con rồng Vương gia đang ở Đế quan và công khai kích động mọi người cùng đi săn rồng."},{"chuong":1402,"tieuDe":"Lập Trường","tomTat":"Thạch Hạo công khai tố cáo Vương gia nhiều lần ám hại mình và tuyên bố muốn giết năm con rồng của gia tộc này, qua đó buộc đối phương phải đưa ra lời giải thích cùng sự bảo đảm. Các cường giả Đế Quan lo ngại một cuộc khai chiến toàn diện sẽ gây nội loạn giữa lúc đại quân dị vực đang uy hiếp, nhưng Tào Vũ Sinh, Thái Âm Ngọc Thỏ và Thiên Giác Nghĩ đều đứng về phía Thạch Hạo. Mạnh Thiên Chính trấn áp ba cao thủ Vương gia, sai giam họ vào tử lao rồi tiếp tục ra tay về phía khu kiến trúc của thế lực này. Người ở tổ đàn kịp thời can thiệp, cam kết đưa ra cách giải quyết thỏa đáng và mời Mạnh Thiên Chính tới thương nghị. Trước khi rời đi, ông trả Lôi Trì đã phong ấn cho Thạch Hạo. Khi mọi người kiểm tra, Lôi Trì thể hiện độ cứng đáng kinh ngạc và dẫn phát lôi điện phản kích người thử phá nó. Những sinh vật giống Chân Long sau đó thấp thoáng xuất hiện trong thành ao và bơi giữa lôi kiếp dịch, khiến Thạch Hạo mời mọi người dùng thần dịch này như thần tửu rồi cùng nghiên cứu bí mật bên trong."},{"chuong":1403,"tieuDe":"Ba Con Rồng","tomTat":"Thạch Hạo quyết định pha một phần Lôi Kiếp Dịch vào rượu để các thiên tài trẻ tuổi cùng thưởng thức trước ngày ra chiến trường. Hắn dùng lượng dịch từng cất trong cốt đỉnh để thử trước và nhận ra dược lực của nó có thể nhanh chóng chữa lành những thương tích sâu tới xương. Thác Cổ Ngự Long góp Bán Thần quả, còn Thạch Hạo đem thi thể mười Vương tộc Dị Vực thu được tại biên quan Đại Xích Thiên ra nướng, khiến buổi tụ hội trở nên náo nhiệt. Giữa cảnh vui vẻ, Thạch Hạo dự cảm cuộc chiến ngoài Đế quan sẽ khiến phần lớn những người đang hiện diện không thể sống tới lần tái tụ sau. Trong lúc kiểm tra Lôi Trì bằng cổ nham thạch, nhóm lão nhân phát hiện bên trong tỏa long uy và có ba sinh linh giống hệt Chân Long ấu tể bơi dưới đáy sâu. Ngay cả Thiên Nhãn của Thạch Hạo cũng không thể nhìn thấu hoàn toàn, vì vậy các lão nhân đề nghị đưa Lôi Trì tới tổ đàn để đại nhân vật kiểm chứng."},{"chuong":1404,"tieuDe":"Kỳ Vật","tomTat":"Thiên Giác Nghĩ say rượu đề nghị mò một sinh linh trong Lôi Trì ra luộc, khiến mọi người bàn luận về khả năng ba sinh linh bên trong là rồng non, nhưng không ai xác định được chân tướng và cuối cùng đề nghị nhờ Mạnh Thiên Chính kiểm tra. Thạch Hạo chuyển sang nghiên cứu thần mang đỏ sậm trong Lôi Trì, cân nhắc giữa việc luyện vào binh khí và dung hợp với thân thể rồi nghiêng về phương án rèn luyện nhục thân. Tề Hoành công bố một kỳ thạch màu vàng lấy từ dị vực, có thể lơ lửng, chứa sinh mệnh tinh khí tinh thuần và hỗ trợ tu luyện. Hắn còn tiết lộ huyết thanh đồng nguyên chứa vật chất Trường Sinh có thể phong ấn sinh linh suốt vạn năm mà vẫn bảo toàn sức sống. Tin tức từ tù binh dị vực dẫn tới giả thuyết An Lan và Du Đà từng khai mở cổ táng địa, tìm thấy ghi chép liên quan đến cảnh giới Bất Hủ chi Đế và phát hiện loại vật chất kỳ dị trong quá trình truy tìm bí mật cổ đại. Cuối cùng, Thác Cổ Ngự Long đưa ra tàn đồ da thú đoạt từ người dị vực, tuyên bố nó liên quan đến bí mật cùng cơ duyên lớn ngoài quan ải và cho biết vùng cấm cổ xưa trên chín tầng trời đã hồi đáp lời mời nhờ manh mối này."},{"chuong":1405,"tieuDe":"Cấm Khu Khách Đến Thăm","tomTat":"Sinh Mệnh Cấm Khu trên Cửu Thiên phá lệ hồi đáp thiệp mời và quyết định cử người tới Đế quan vì quan tâm đến tàn đồ quan ngoại. Tại Bích Lạc Hồ, Thác Cổ Ngự Long cùng các anh kiệt nghiên cứu tấm bản đồ chỉ tới khu vực nằm giữa Thiên Thú sâm lâm, Cổ Táng Khu và Thần Dược sơn mạch, nhưng phần chỉ dẫn quan trọng đã bị khuyết mất. Cấp cao Đế quan từng phái cường giả dò xét nơi này, song tất cả đều một đi không trở lại. Một con gà trống già gần như trụi lông tiến lên đảo khiến mọi người lầm tưởng nó là khách cấm khu, trong khi vị khách thật sự là lão giả nhỏ bé ẩn trên lưng nó. Lão giả giải thích tọa kỵ gần như mất hết ngũ giác vì di chứng chiến đấu. Khi được hỏi về chân trái bị chém vẫn rỉ máu lam, ông tiết lộ vết thương ấy đã tồn tại từ một trận chiến cách đây một trăm năm mươi vạn năm."},{"chuong":1406,"tieuDe":"Vùng Cấm Con Rễ","tomTat":"Sứ giả thấp bé của vùng cấm tiết lộ mình đã sống hơn một triệu rưỡi năm nhưng vẫn không thể phục hồi chiếc chân bị một cường giả bí ẩn đánh mất, bởi pháp lực của đối phương còn lưu lại trong vết thương. Ông thay một tiểu chủ nhân đang chuẩn bị độ đại kiếp tới dự hội và thẳng thắn xác nhận mọi thiên kiêu từng xông nhầm vào vùng cấm đều đã hình thần câu diệt. Khi bàn về thiên kiếp, ông cho biết trong lôi kiếp có thể xuất hiện vật liệu vạn cổ hiếm có, từng có thần thạch đánh nát một chí cường giả rồi được chính người sống sót luyện thành vô thượng chí bảo. Xem tấm da thú cổ, ông nhận ra địa điểm được đánh dấu nằm giữa Thiên Thú sâm lâm, Cổ táng khu và Thần Dược sơn mạch, đồng thời cho biết chủ nhân mình từng truy tìm nơi này nhưng mất dấu, còn Dị vực cũng đang tìm cách tiếp cận. Lo Vương gia sẽ mật báo trước, Thạch Hạo chủ động thừa nhận mình vừa vượt mạnh nhất thiên kiếp và công khai Lôi Trì đoạt được trong kiếp. Sứ giả vùng cấm lập tức thất thố, ôm Lôi Trì kiểm tra nhiều lần rồi bất ngờ đề nghị Thạch Hạo cưới tiểu thư nhà mình và vào vùng cấm ở rể."},{"chuong":1407,"tieuDe":"Dục Cầm Cố Túng","tomTat":"Ông lão vùng cấm né tránh câu hỏi về chủng tộc của chủ nhân rồi ngỏ ý chọn Thạch Hạo làm rể, hứa rằng hắn vẫn có thể bình an ngay cả khi một giới bị diệt. Thạch Hạo không muốn nhận lời nên viện cớ trong nhà đã có nhiều nàng dâu và hỏi liệu tiểu thư vùng cấm có chịu gả tới hay không, khiến ông lão nghi hắn đang dùng kế dục cầm cố túng. Tào Vũ Sinh nhân cơ hội tự tiến cử, nhưng lời đùa lại bộc lộ nỗi sợ bị chôn qua vạn cổ và tỉnh dậy khi mọi bằng hữu đều đã qua đời. Sau đó ông lão khuyên Thạch Hạo dâng Lôi Trì cho chủ nhân vùng cấm, đồng thời cảnh báo vật này có thể liên quan tới một nơi khó tưởng tượng hoặc sào huyệt do Chân Long dựng nên. Khi Thạch Hạo dọa nấu ba sinh linh trong ao, ông lão cho rằng hành động ấy có thể dẫn tới trời phạt vì Lôi Trì mang nhân quả cực lớn. Cuối cùng, ông phát hiện tảng đá do Tề Hoành lấy ra chính là nguồn khí tức Trường Sinh trong cung điện và bên trong chứa lượng vật chất Trường Sinh nồng đậm."},{"chuong":1408,"tieuDe":"Tiên Nguyên","tomTat":"Tề Hoành đưa khối đá lấy từ dị vực cho ông lão vùng cấm xem và được xác nhận đó là tiên thiên chi tinh đã nhiễm Trường Sinh vật chất. Ông lão đặt tên vật chất này là Tiên Nguyên, giải thích dạng rắn có thể phong ấn Chí Tôn lâu dài, còn dạng lỏng đủ sức phong ấn Chân Tiên và giúp Bất Hủ giả trường tồn qua vạn cổ. Chân Tiên, Bất Hủ và Tiên Vương đều không thể luyện chế Tiên Nguyên; khả năng ấy chỉ thuộc về cảnh giới bất tử chi Đế mà An Lan và Du Đà đang tìm kiếm nhưng được cho là không tồn tại. Khi Thạch Hạo dò hỏi về Thái Sơ cổ quáng, ông lão tiết lộ nơi này từng chôn vùi toàn bộ sinh linh của một vùng cấm, đồng thời khiến dòng họ Độc Cô và Chí Tôn cung điện chịu tổn thất nặng nề. Cổ quáng còn có thể chứa một phần Cổ Táng Khu và một thông đạo nối tới địa điểm chưa rõ. Cuối cùng, Thạch Hạo kể rằng mình từng tiến vào nơi đó, sống sót trở ra và nhìn thấy một cây Trường Sinh dược đã thành tinh, khiến ông lão đặc biệt kinh ngạc."},{"chuong":1409,"tieuDe":"Tương Lai Khủng Bố","tomTat":"Mọi người biết một đội nhân mã của cấm khu từng bị chôn vùi trong Thái Sơ cổ quáng, qua đó hiểu thêm mức độ nguy hiểm của nơi này. Lão già đến từ cấm khu đánh giá Thạch Hạo khác thường và muốn đưa hắn đi, nhưng Thạch Hạo từ chối vì còn nhiều vướng bận, chỉ chấp nhận nếu cấm khu chịu tham chiến với Dị Vực. Sau câu chuyện vui quanh Lôi Trì, lão già dự báo thời đại mạt pháp sẽ khiến Trường Sinh vật chất tiêu vong, tài nguyên suy giảm, tuổi thọ cao thủ rút ngắn và con đường thành Tiên gần như đoạn tuyệt. Trước lời chất vấn về thái độ đứng ngoài, ông giải thích rằng các cấm khu có nguồn gốc khác nhau, thậm chí một số không thuộc Cửu Thiên Thập Địa, còn những sinh linh từng bảo vệ thế giới này đã rút lui vì nguyên nhân riêng. Thạch Hạo từ đó nhớ lại tiểu thế giới thần bí ngoài biên cương Đại Xích Thiên, nơi cô gái trong quan tài từng bảo vệ Cửu Thiên rồi đoạn tuyệt với ngoại giới. Lão già tiếp tục tiết lộ thiên cơ do chủ nhân mình thôi diễn: bất kỳ ai can thiệp và nhiễm nhân quả trong những năm tháng sắp tới đều sẽ chết. Kỷ nguyên hiện tại sắp khép lại để nhường chỗ cho một cuộc đại thanh toán lôi cuốn sinh linh từ nhiều kỷ nguyên, đáng sợ hơn cả Tiên Cổ đại chiến. Chân tướng ấy từng khiến chủ nhân cấm khu bạc nửa mái tóc, chỉ để lại lời cảnh báo rằng một tồn tại chưa rõ sắp trở về cùng bốn chữ độc đoán vạn cổ."},{"chuong":1410,"tieuDe":"Tiểu Tụ","tomTat":"Sau khi ghi nhớ địa đồ để trở về phục mệnh, vị khách vùng cấm từ chối lời giữ lại của các đại nhân vật Đế quan, cưỡi gà trống lớn rời Bích Lạc hồ và căn dặn Thạch Hạo giữ kỹ Lôi Trì. Cuộc tụ hội giải tán, các tu sĩ trở về báo cáo sư trưởng hoặc bế quan chuẩn bị cho chiến trường cùng những biến động tương lai. Thạch Hạo cùng Tào Vũ Sinh, Thái Âm Ngọc Thỏ, Thiên Giác Nghĩ, Hoàng Điệp và Tiểu Kỳ Lân mở tiểu tụ tại bộ lạc Thạch Tộc, chia nhau huyết nhục sinh linh Dị vực và lôi kiếp dịch. Qua lời các bạn, Thạch Hạo biết Thanh Y và Nguyệt Thiền đều bị đưa tới tổ đàn, khiến hắn lo hai thân vốn cùng một người sẽ bị ngoại lực ép hợp nhất. Hoàng Điệp tuyên bố muốn độ kiếp, còn Đả Thần Thạch vẫn ngủ say trên tóc Thạch Hạo. Mạnh Thiên Chính từ tổ đàn giáng lâm, mở phong ấn Lôi Trì và trấn áp tia thần mang định đào thoát. Sau khi nhìn thấy ba sinh linh giống Chân Long dưới đáy ao, ông bất ngờ yêu cầu Thạch Hạo thả Lôi Linh vào Lôi Trì, khiến mọi người đều kinh ngạc."},{"chuong":1411,"tieuDe":"Sống Ấn Ký","tomTat":"Mạnh Thiên Chính đề nghị dùng ba Lôi Linh để kiểm chứng bản chất những bóng Chân Long dưới đáy Lôi Trì, vì vậy Thạch Hạo rút phần lớn Lôi Kiếp Dịch sang cốt đỉnh rồi thả chúng vào ao. Lôi Linh màu vàng chồng khít với một bóng Chân Long, giúp Đại trưởng lão xác nhận đó chỉ là lạc ấn chứ không phải sinh vật sống. Quá trình thăm dò tiếp theo cho thấy ba lạc ấn có thể do Chân Long lưu lại và chứa quy tắc mơ hồ liên quan tới nguồn gốc cùng sự sáng tạo sinh mệnh, từ đó dẫn tới giả thuyết Lôi Linh là sinh vật chưa hoàn tất tiến hóa. Việc kiểm tra nguyên thần không đem lại bí mật đáng kể vì cả ba Lôi Linh vẫn còn non trẻ. Thạch Hạo giao Lôi Trì cùng ba Lôi Linh cho Mạnh Thiên Chính bế quan tìm hiểu, hy vọng ông có thể tiến thêm một bước. Đại trưởng lão sau đó cho biết Vương gia đã trả giá lớn tại Đế quan và tiếp tục đưa tới một giọt hoạt huyết của cha Vương Trường Sinh để bồi tội. Cuối cùng, ông rút thần mang do Trảm Tiên Dao Cầu để lại khỏi Lôi Trì, chuẩn bị giúp Thạch Hạo luyện nó vào thân thể để tăng mạnh sức công phạt."},{"chuong":1412,"tieuDe":"Luyện Thần Mang","tomTat":"Mạnh Thiên Chính trấn áp đạo thần mang còn lại sau khi Trảm Tiên Trát Đao tan đi trong Lôi Trì, còn giọt Tiên huyết sống sót cũng được xem là chí bảo đủ khiến Chí Tôn động lòng. Thạch Hạo không muốn dùng Tiên huyết để lập tức tiến vào Trảm Ngã Cảnh vì dự định tới quan ngoại Tiên mài giũa, đồng thời từ chối luyện thần mang vào binh khí để tránh lệ thuộc ngoại vật. Dưới sự hộ pháp của Mạnh Thiên Chính, hắn chọn dung hợp thần mang với ngón trỏ tay trái, nơi thường dùng để thi triển kiếm quyết. Dù đã vận dụng Côn Bằng pháp, Liễu Thần pháp trảm tiên, lôi đình, Luân Hồi thần thông, chân kinh và ba đóa Đại đạo chi hoa, hắn vẫn bị thần mang phá nát huyết nhục và làm nứt xương ngón tay. Theo đề nghị của Mạnh Thiên Chính, Thạch Hạo dẫn một tia Tiên huyết từ thủy tinh xuống ngón tay để trợ luyện. Thần mang lập tức cảm ứng rồi chủ động lao tới chém tia Tiên huyết, khiến những người chứng kiến kinh ngạc trước bản chất Trảm Tiên của nó."},{"chuong":1413,"tieuDe":"Lại Xuất Quan","tomTat":"Thạch Hạo tiếp tục dung hợp thần mang trảm tiên vào ngón trỏ trái, chịu đựng cảnh ngón tay liên tục bị phá nát rồi tái sinh nhờ giọt Tiên huyết cuối cùng. Mạnh Thiên Chính dùng pháp lực hỗ trợ suốt nửa tháng, sau đó thần mang và Tiên huyết giao hòa, hóa thành hoa văn thấm vào máu thịt cùng xương cốt. Qua hai tháng bế quan củng cố, ngón trỏ trái của Thạch Hạo hoàn thành niết bàn, có thể phá bảo cụ mạnh và phóng ra thần mang đỏ sậm khi pháp lực cạn kiệt. Hắn nảy ra ý tưởng lột xác toàn bộ tứ chi, rồi xuất quan để tìm cơ hội đột phá Trảm Ngã cảnh trong thực chiến. Thạch Hạo lặng lẽ theo đại quân ra chiến trường quan ngoại, đồng thời dự định tìm kiếm cơ duyên tại Thần Dược Sơn Mạch và những mật thổ khác. Tại chiến trường, hắn biết Vương gia Năm Cái Long đang chịu phạt vì từng muốn hại mình và vừa giết một cường giả tuyệt đỉnh của Vương tộc Dị vực. Dị vực tiếp tục công khai khiêu chiến Hoang, trong khi tin tức về một Hoàng tộc cường giả bí ẩn có thể dùng tu vi Trảm Ngã giết đại kỵ sĩ Độn Nhất khiến Thạch Hạo đặc biệt chú ý."},{"chuong":1414,"tieuDe":"Mục Tiêu Mười Đại Cao Thủ","tomTat":"Thạch Hạo dò hỏi về sinh linh Đế Tộc vô danh từng quét ngang chiến trường, đồng thời biết dị vực vẫn công khai gọi Hoang ra quyết chiến trước hai quân. Che giấu hình dáng, hắn tiến sâu vào chiến trường và xác nhận thực lực sau độ kiếp của mình đã đủ trực tiếp giết sinh linh Trảm Ngã cảnh dù vẫn ở Hư Đạo cảnh. Khi bị một quái vật tóc đỏ thân người đuôi rắn tập kích, hắn thử dẫn tinh khí từ Chiến Tiên dao cầu thành thần mang đỏ sậm, dễ dàng xuyên cắt đối thủ nhưng cũng gần như cạn sạch tinh khí. Sau đó, Thạch Hạo cứu một thiên tài Đế Quan đang bị em trai Bích Nhãn Kim Lân Sư Vương áp đảo bằng Sư tử Hống. Hắn dùng lôi đình đánh trọng thương hung sư, rồi lấy đao chớp giật phá tổ thuật phòng ngự và chém chết đối phương. Bích Nhãn Kim Lân Sư Vương nhận tin em ruột tử trận liền lao tới chiến trường, còn Thạch Hạo chủ động ở lại, quyết định bắt đầu kế hoạch săn giết từng người trong mười đại cao thủ trẻ tuổi dị vực từ Sư Vương."},{"chuong":1415,"tieuDe":"Đánh Giết","tomTat":"Bích Nhãn Kim Lân Sư Vương xông tới chiến trường báo thù sau khi Thạch Hạo thừa nhận đã giết em trai nó. Để che giấu thân phận Hoang, Thạch Hạo dùng Thất Thập Nhị Biến thay đổi chân thân, tinh lực và khí chất, đồng thời chỉ vận dụng Nguyên Thủy Chân Giải cùng cốt văn phổ thông. Sư vương liên tiếp thi triển hoàng kim chi hỏa, Sư tử Hống, Ngũ hành tổ thuật, vảy vàng, gai xương và đồng thuật Lạc lối, nhưng các đợt công kích đều bị hóa giải. Lạc lối khiến nguyên thần Thạch Hạo cứng lại trong khoảnh khắc, song hắn nhanh chóng khôi phục. Thạch Hạo vận chuyển Bất Diệt Kinh, dồn toàn bộ thần lực vào sáu quyền để phá nát thân thể Sư vương, rồi bắt và nghiền diệt nguyên thần đang bỏ chạy. Một trong mười đại cao thủ trẻ tuổi Dị vực chết trận, còn Thạch Hạo không lưu danh mà dùng Súc địa thành thốn tiến sâu hơn vào chiến trường. Cái chết này khiến sinh linh Dị vực kinh hãi và bắt đầu tính tới việc phải điều động Đế Tộc."},{"chuong":1416,"tieuDe":"Chư Vương Tới Đông Đủ","tomTat":"Cái chết của Bích Nhãn Kim Lân Sư Vương khiến dị vực chấn động, kéo theo nhiều cường giả Trảm Ngã và Độn Nhất tới truy tìm hung thủ, còn Đế quan điều đại kỵ sĩ ra ngăn cản. Thạch Hạo liên tục thay đổi dung mạo để ẩn mình giữa chiến trường, đồng thời tận mắt chứng kiến tu sĩ Thiên Thần và Hư Đạo của hai giới chết hàng loạt giữa sa mạc nhuốm máu. Khi hai chiến binh Đế quan trọng thương vẫn cự tuyệt đầu hàng, hắn kịp thời ra tay cứu họ. Thạch Hạo vận chuyển áo nghĩa Bất Diệt Kinh tới cực hạn, đánh bại rồi giết cả thân thể lẫn Nguyên Thần của một lão giả Trảm Ngã cảnh thuộc dị vực. Vũ Phong sau thời gian bế quan dưỡng thương đã tiến hóa và tăng thực lực, nhưng không nhận ra đối thủ trước mặt chính là Hoang. Vũ Xà Song Vương xếp thứ bảy và thứ tám trong mười đại cao thủ trẻ tuổi tiếp tục xuất hiện, sau đó thêm một Vương trẻ tuổi chưa rõ tên cũng chạy tới. Trước nhiều Vương dị vực đang hội tụ, Thạch Hạo công khai thách họ liên thủ và chuẩn bị cho cuộc giao chiến mới."},{"chuong":1417,"tieuDe":"Đánh Giết Chư Vương","tomTat":"Thanh Đằng Vương hội quân với Vũ Phong và Vũ Xà Song Vương để vây giết Hoang, nhưng cả bốn không biết đối thủ vô danh trước mặt chính là Thạch Hạo đang cố ý thu liễm khí cơ. Vũ Phong thi triển Bất hủ thiên đao, còn Thạch Hạo vận chuyển Bất Diệt Kinh, Nguyên Thủy Chân Giải và bí mật dung hợp nhiều bảo thuật vào quyền ấn để đánh hắn trọng thương. Khi Vũ Phong nhận ra Hoang và định truyền âm cảnh báo, Thạch Hạo quấy nhiễu thần niệm rồi đánh nổ cả thân thể lẫn Nguyên Thần của hắn. Vũ Xà Song Vương cùng Thanh Đằng Vương lập tức hợp kích bằng tóc rắn độc, cánh vàng và dây leo, nhưng đều không thể chống lại thân thể và sức công phạt của Thạch Hạo. Thạch Hạo xé đôi Vũ Xà Vương huynh trưởng, đánh xuyên mi tâm người em rồi dùng pháp ấn ép Thanh Đằng Vương hiện nguyên hình và chấn nát hắn. Khi sinh linh dị vực định cùng xông lên, tu sĩ Cửu Thiên cũng lao vào giao chiến, khiến trận đấu giữa các vương giả chuyển thành hỗn chiến. Việc bốn vương giả tử trận, cộng với cái chết trước đó của Bích Nhãn Kim Lân Sư Vương, đồng nghĩa dị vực đã mất năm trong mười đại cao thủ trẻ tuổi chỉ trong một ngày."},{"chuong":1418,"tieuDe":"Hắc Ám Chi Nhật","tomTat":"Sau khi năm cao thủ trẻ tuổi hàng đầu Dị Vực tử trận, Thạch Hạo tiếp tục xông vào đội ngũ đối phương, dùng quyền ấn và nhiều bảo thuật giết hàng trăm sinh linh. Hắn ngăn các tu sĩ Đế Quan đang bị thương truy sát vì đoán rằng nhân vật lớn Dị Vực sẽ nhanh chóng tới báo thù, rồi chui xuống đại mạc, thay đổi dung mạo và mặc giáp trụ của người chết để ẩn vào khu vực có cao thủ Đế Quan tọa trấn. Phía Dị Vực chấn động khi xác nhận năm thiên kiêu thuộc nhóm mạnh nhất đã mất mạng trong một ngày và nghi ngờ cả Bích Nhãn Kim Lân Sư Vương cũng chết dưới tay cùng một người trẻ tuổi Nhân tộc. Thúc tổ của Vũ Thiên Vương cùng Huyền Tổ của Vũ Xà Song Vương kéo tới, ra lệnh truy tìm hung thủ và tuyên bố báo thù cho hậu bối. Nhiều Vương tộc tập kết khiến sát khí phủ kín chiến trường, thậm chí xuất hiện khí tức Chí Tôn, buộc các đại kỵ sĩ Đế Quan đứng tuyến đầu phòng bị. Một số nhân vật cổ xưa Dị Vực nghi ngờ hậu duệ của nhóm sinh linh bí ẩn đã quay lại, trong khi thế hệ trẻ đồng loạt dập đầu cầu xin các lão tổ tới cổ địa mời truyền nhân Đế tộc xuất thế."},{"chuong":1419,"tieuDe":"Đi Xa","tomTat":"Trong lúc nghe lén tu sĩ dị vực, Thạch Hạo biết Đế Tộc không thể tùy tiện mời ra và Hạc tộc chỉ còn cách địa vị ấy nửa bước nhờ Hạc Vô Song. Dị vực cũng lo ngại Đế quan có thể nhận được sự trợ giúp từ nhóm sinh linh thần bí từng can thiệp đại chiến hai giới, đồng thời đặt kỳ vọng vào Hạc Tử Minh để đối phó lớp trẻ Cửu Thiên. Sau tiếng kèn lui binh, tin năm đại cao thủ trẻ tuổi tử trận gây chấn động dị vực, khiến Hạc Tử Minh xuất quan và năm tộc liên quan chuẩn bị báo thù. Thạch Hạo không trở về Đế Thành mà lặng lẽ rời đại quân, vận dụng nhiều thân pháp để vượt qua đại mạc. Một tu sĩ Độn Nhất bí mật bám theo và ra tay trấn áp hắn khi tới gần rìa hoang mạc. Thạch Hạo lấy Đại La kiếm thai chống trả, khiến kiếm thai phát sáng dữ dội dưới áp lực. Đúng lúc nguy cấp, Cổ thụ Thiết Huyết từ Thần Dược Sơn Mạch vươn cành đánh bật bàn tay lớn, giúp hắn tiến vào vùng núi bí ẩn mà kẻ truy kích không dám theo."},{"chuong":1420,"tieuDe":"Thần Dược Sơn Mạch","tomTat":"Thạch Hạo phát hiện một đại tu sĩ Độn Nhất Cảnh từ phía Đế Quan che giấu thân phận để phục kích mình, nhưng kẻ này không dám tiến gần Thiết Huyết Cổ Thụ và nhanh chóng rút vào sâu trong đại mạc. Không thể tiếp tục men theo bên ngoài khi đang bị theo dõi, Thạch Hạo buộc phải tiến sâu vào Thần Dược Sơn Mạch để tìm mật thổ được ghi trên tấm da thú. Hắn bị hàng triệu ma cầm đầu sư tử bao vây và phải dùng Bảo thuật Lôi Đế mở đường máu. Thủ lĩnh ma cầm Độn Nhất Cảnh tiếp tục truy sát dưới lòng đất, lợi dụng trường vực kỳ dị làm chậm Thạch Hạo rồi đánh hắn ho ra máu. Thạch Hạo chạy vào một bãi xương chứa hài cốt của nhiều cường giả, khiến ma cầm khiếp sợ không dám tiến vào nhưng vẫn đứng ngoài chặn đường lui. Tại đó, hắn phát hiện cả đàn Thần dược nhiều màu có thể chạy và độn thổ. Cùng lúc, một sinh linh từ phía Đế Quan vượt Biên Hoang và đại mạc sang Dị Vực, nhận thấy đại đạo nơi này tương hợp với mình và mong chờ gặp một nhóm người chưa rõ danh tính."},{"chuong":1421,"tieuDe":"Tiên Kim Sinh Linh","tomTat":"Thạch Hạo tiến qua vùng đất chết khô héo và dùng Võ đạo Thiên nhãn phát hiện ít nhất chín cây thần dược thành tinh trong dãy núi phía trước. Khi hắn định dùng pháp lực bắt giữ chúng, tràng vực kỳ dị vặn vẹo thời không và làm xuất hiện một con Hoàng Kim Ngưu do Hoàng Đạo Tiên Kim thông linh hóa thành. Bảo thuật của Thạch Hạo không thể làm tổn thương thân thể Tiên kim, trong khi tiếng rống và thần lực lâu đời của đối phương buộc hắn phải từ bỏ việc hái thuốc. Một cây Thiên Thần thụ bí mật truyền âm chỉ đường, đồng thời khiến hắn nhớ lại bí mật bốn cây cùng nguồn có thể hợp nhất thành Trường Sinh tiên dược. Dù được trợ giúp, Thạch Hạo vẫn bị Hoàng Kim Ngưu truy sát suốt ba ngày, nhiều lần suýt chết và chịu trọng thương. Cùng lúc đó, một sinh linh từ Đế quan đã sang dị vực tiết lộ rằng Hoang mắc kẹt tại Thần Dược Thần Mạch. Tin tức lan truyền trong các Vương tộc, khiến Hạc Tử Minh và những cao thủ trẻ tuổi dị vực lập tức chuẩn bị tụ hội để săn giết hắn."},{"chuong":1422,"tieuDe":"Nguy Cảnh","tomTat":"Tại vùng đất của một Bất Hủ giả trong Dị vực, một sinh vật hình người đến từ Đế quan được tiếp đón trọng hậu, nhận lệnh bài thông hành và bàn chuyện hợp tác nhằm giết Hoang. Tin tức lan rộng khiến nhiều tu sĩ trẻ Dị vực kéo tới phong tỏa các yếu đạo ngoài Thần Dược Sơn Mạch. Bên trong sơn mạch, Thạch Hạo bị Hoàng Kim Ngưu có sức mạnh vượt đại tu Độn Nhất truy sát đến gần giải thể, dù đã dẫn nó vào sào huyệt ma cầm để tìm cơ hội thoát thân. Tiếng rống của Hoàng Kim Ngưu phá sập địa quật, giết hàng trăm nghìn ma cầm và tiếp tục chấn Thạch Hạo ngã trong vũng máu, không còn sức chạy trốn. Từ lời gọi của đám tu sĩ bên ngoài, Thạch Hạo suy đoán có sinh linh Đế quan cấu kết với Dị vực và tiết lộ hành tung của mình. Trong tuyệt cảnh, hắn giả giọng người Dị vực tung tin Hoang đã hái hơn mười cây thần dược để kích lòng tham của lực lượng ngoài núi, rồi rút Đại La kiếm thai chờ họ tiến vào tạo ra biến số."},{"chuong":1423,"tieuDe":"Quần Địch","tomTat":"Nhiều đội cường giả trẻ tuổi Dị vực xâm nhập Thần Dược Sơn Mạch và liên tiếp chịu thương vong trước những huyết đằng khát máu cùng các sinh linh bản địa mất linh trí. Huyết đằng lão tổ thức dậy trong một thung lũng phủ sương máu, dùng nhánh dây xuyên trúng đại tu sĩ Độn Nhất và buộc người này phải tự chém bỏ vai trái cùng một phần thân thể để thoát chết. Một số đội khác vượt qua vùng nguy hiểm, tiến đến chiến trường nơi Thạch Hạo đang nằm cạnh Hoàng Kim Ngưu và lầm tưởng hắn đã bị đánh trọng thương. Dựa vào một đại tu sĩ Độn Nhất đi cùng, quần địch công khai chế nhạo Thạch Hạo, tranh nhau quyền chém đầu hắn và chiếm đoạt thần dược, Đại La kiếm thai cùng Hoàng Đạo Tiên Kim. Thạch Hạo không phản kích mà cố ý nói mình đã đại chiến với Kim Ngưu suốt một ngày một đêm, khiến những kẻ còn nghi ngại yên tâm tiến lại gần. Khi đám Dị vực định thu phục Hoàng Kim Ngưu, nó thôi quan sát Đại La kiếm thai, khóa mắt vào họ và tỏa ra khí tức khủng khiếp. Quần địch lúc ấy mới nhận ra mình đã mắc lừa Thạch Hạo và rơi vào tình thế cực kỳ nguy hiểm."},{"chuong":1424,"tieuDe":"Giết Địch","tomTat":"Hoàng Kim Ngưu tỉnh lại và nổi giận khi nghe nhóm tu sĩ Dị Vực muốn bắt mình làm vật liệu luyện khí, liền dùng tiếng rống, thân thể và sừng vàng giết gần hai mươi người. Một đại tu sĩ Độn Nhất dùng đồng tháp, nhiều thần thông và tổ kiếm trận 9.999 kiếm quang đối phó nó nhưng đều thất bại, còn bị chém đứt hai tay rồi phải bỏ chạy. Trong lúc Hoàng Kim Ngưu truy sát người này, Thạch Hạo uống lôi kiếp dịch và vận chuyển ba đạo tiên khí cùng Luân Hải để chữa thương tổn bản nguyên. Huyết Ngao dẫn tám sinh linh Dị Vực khác lần theo dấu vết, phát động sát trận nhằm giết hắn khi đang suy yếu. Thạch Hạo dùng lực Côn Bằng chém chết Huyết Ngao, sau đó cưỡng ép thi triển hàm nghĩa cao nhất hiện tại của Bảo thuật Lôi Đế để gọi xuống lôi đình mang khí tức thiên kiếp. Phối hợp sấm sét với Đại La kiếm thai và sức mạnh thân thể, hắn giết sạch cả chín kẻ truy sát, trong đó chém nguyên thần sinh linh một sừng và xé chết nam tử tóc lam. Dù thương thế vẫn nghiêm trọng, Thạch Hạo rời chiến trường với quyết tâm tiêu diệt toàn bộ những kẻ Dị Vực đã tiến vào vùng núi."},{"chuong":1425,"tieuDe":"Hoàng Đạo Hang Ổ","tomTat":"Vết thương đại đạo của Thạch Hạo bùng phát, lan vào bổn nguyên và thần hồn, khiến hắn ho ra máu và gần như không thể đứng vững. Hắn đồng thời vận chuyển Liễu Thần pháp, Luân Hải, ba đạo tiên khí cùng nhiều cổ kinh để trị thương, nhưng một lực lượng phản phệ vẫn suýt đánh tan toàn bộ hệ thống áp chế. Từ đó, hắn nghi ngờ thương thế có liên quan đến nhân quả Thiên Kiếp, Lôi Trì và tinh túy Trảm Tiên Dao Cầu từng đoạt được, đồng thời nhớ tới Lôi Đế, Tiểu Tháp và Liễu Thần. Dựa vào kinh nghiệm từng sống sót sau nguyền rủa Tiên điện, Thạch Hạo quyết tâm chiến thắng đạo thương và biến lần chữa trị này thành cơ hội lột xác. Sau khi tạm ổn định, hắn quay lại vùng đất đỏ sẫm và chọn hang ổ Hoàng Kim Ngưu làm nơi ẩn náu. Đi sâu xuống lòng đất, hắn phát hiện nham bích đều là Hoàng Đạo thạch, từ đó nghi ngờ nơi đây còn thai nghén tiên kim hoặc một sinh linh khác. Cuối cùng, Thạch Hạo tìm thấy Hoàng Kim ao chứa chất lỏng màu vàng và Tiên gia tinh khí nồng đậm, nhận ra hang ổ này có thể cất giấu một tạo hóa lớn."},{"chuong":1426,"tieuDe":"Tiên Trấp Kim Dịch","tomTat":"Thạch Hạo tìm thấy một ao nhỏ giữa Hoàng Đạo Thạch và xác nhận nơi đây từng dựng dục sinh linh từ Hoàng Đạo Tiên Kim, rất có thể chính là nguồn gốc của Hoàng Kim Ngưu. Hắn ngồi trong ao hấp thu Tiên trấp Kim dịch, nhờ sinh mệnh tinh hoa trong đó nuôi dưỡng nhục thân và thần hồn, tạm thời trung hòa tổn hại do bản nguyên trọng thương nhưng không thể chữa khỏi vết thương đại đạo. Khi dò xét các khe dưới đáy ao, hắn phát hiện kim dịch cùng đại đạo khí tức đều đến từ nơi sâu hơn, song quang mang phía dưới đủ sức làm thần thức bị thương. Khí tức Tiên đạo trong kim dịch khiến ba đạo Tiên khí của hắn liên tục tụ tán rồi bất ngờ bị đánh tan vào huyết nhục và xương cốt. Ngay sau đó, đạo thủy khí từng biến mất nhiều năm trước tái hiện và chủ động hấp thu bí lực trong ao. Thạch Hạo nhớ lại lời Mạnh Thiên Chính cảnh báo rằng mẫu khí này vốn phải rời đi sau khi lưu dấu sinh thành các Tiên khí khác, còn cưỡng ép giữ lại có thể khiến nó trở thành gông xiềng phản phệ chủ nhân. Dù đang mang thương thế và biết rõ nguy cơ, hắn vẫn quyết định thu nhận thủy khí, đồng thời chuẩn bị tiếp tục thăm dò bí mật nằm sâu dưới lòng đất."},{"chuong":1427,"tieuDe":"Phúc Địa","tomTat":"Thạch Hạo phát hiện lão đạo nhân ngồi trên chiến xa rách thực chất là sinh vật do Hoàng Đạo Tiên Kim hóa thành, đã chết nhưng uy thế còn sót lại vẫn gần như khiến thân thể và thần hồn hắn tan vỡ. Sau gáy lão có một lỗ máu chảy máu vàng, Nguyên Thần đã biến mất, còn vết thương hướng thẳng về hang cổ màu đen mà ngay cả đoàn Tiên hỏa cũng kiêng kỵ. Từ xác Kim Ngưu Tiên Đạo trong địa quật và Hoàng Kim Ngưu giống hệt trên mặt đất, Thạch Hạo nghi phúc địa này có thể giúp sinh vật Tiên kim niết bàn tái sinh, nhưng hắn không mạo hiểm tiến vào hang để kiểm chứng. Trở lại chân thân trong ao vàng, hắn hấp thu Tiên trấp ngọc dịch hình thành từ sương vàng của Hoàng Đạo thạch, khiến thủy khí hoàn toàn thành hình và cắm rễ tại Luân Hải. Ba đạo tiên khí sau đó lưu chuyển trong cơ thể, lao khỏi thiên linh cái và hóa thành ba đóa đại đạo chi hoa. Trong đóa hoa trung tâm xuất hiện một tiểu nhân mơ hồ, đánh dấu sinh linh thứ hai hình thành trong dị tượng đại đạo của Thạch Hạo."},{"chuong":1428,"tieuDe":"Có Động Thiên Khác","tomTat":"Thạch Hạo hấp thu Tiên trấp Kim dịch để khôi phục rồi đưa Thần thức xuyên qua khe đáy ao, lần theo dòng dịch vàng vào vùng lòng đất cấu thành từ Hoàng Đạo Thạch. Màn sáng kim quang tại đây liên tục làm tổn thương Thần thức; ngay cả Chân Long nghịch lân, Đại La Kiếm Thai và Vạn Linh Đồ cũng không giúp hắn vượt qua. Đoàn Tiên Hỏa thần bí bất ngờ tự xuất hiện, đốt thủng lớp phòng hộ và tạo cơ hội cho một sợi Thần niệm của Thạch Hạo tiến vào mật địa. Bên trong, hắn phát hiện chiến xa cổ vỡ nát được tế luyện hoàn toàn từ Hoàng Đạo Tiên Kim cùng tàn thể Kim Ngưu mang những lỗ tên, vết rìu và đao ấn chứa đạo vận Tiên đạo. Tiên Hỏa tiếp tục soi rọi và sao chép đại đạo chân nghĩa lưu trong các thương tích ấy. Ở nửa buồng xe còn lại, Thạch Hạo nhìn thấy một lão đạo nhân tóc vàng râu vàng mặc đạo bào Hoàng Đạo Tiên Kim; uy thế còn sót lại của ông khiến thân thể hắn gần như nổ tung. Phía sau lưng lão đạo nhân còn có một hang cổ nhỏ đen như mực bị che khuất hơn phân nửa, để lại bí mật chưa được khám phá."},{"chuong":1429,"tieuDe":"Đệ Nhị Sinh Linh","tomTat":"Đóa Đại đạo chi hoa giữa nở rộ, tập trung đạo hạnh và sức chiến đấu đang dâng lên của Thạch Hạo để thai nghén một tiểu nhân mang khuynh hướng chủ chiến, chủ sát. Tinh hoa trong thần bí cổ trì tiếp tục rèn giũa xương cốt, huyết nhục và các môn trong cơ thể hắn, đồng thời ổn định Thủy khí và nuôi lớn ba đạo Tiên khí, nhưng bản nguyên thương vẫn chưa được chữa khỏi. Thạch Hạo nhận ra con đường lấy thân làm chủng của mình rất khó trở thành một hệ thống tu luyện mà người khác có thể noi theo. Thủy khí bất ngờ rời Luân Hải, hóa thành Chân Long xông vào đóa hoa thứ hai rồi biến thành hoa văn gông xiềng, phong bế đệ nhị sinh linh với ngoại giới. Từ quan hệ giữa Thủy khí và ba đạo Tiên khí, Thạch Hạo quyết định mạo hiểm phân giải rồi nung nấu Thủy khí vào chân thân để giành quyền nắm giữ toàn bộ sức mạnh. Khi hắn vận chuyển Nguyên Thủy Chân Giải để tìm biện pháp, vạn linh do cốt văn hóa thành hút sinh khí quanh cổ trì và bộc lộ hơi thở sự sống hưng thịnh như sắp niết bàn phục sinh."},{"chuong":1430,"tieuDe":"Tiên Khí Tiến Hóa","tomTat":"Thạch Hạo nhập định trong thần bí cổ trì và tìm cách giải cứu đệ nhị sinh linh đang bị Thủy khí phong bế. Hắn thử bắt giữ mục tiêu, dùng Đại La Tiên Kiếm và thi triển tinh túy Trảm Tiên Trát Đao, nhưng chỉ có đòn đánh sau cùng lay động được Thủy khí mà vẫn không thể chém đứt nó. Nhận ra hiện tại chưa có cách hóa giải mối họa, Thạch Hạo tạm gác việc này và tiếp tục áp chế Trảm Ngã Cảnh để củng cố đạo cơ. Hắn chọn Tiên Cổ pháp làm con đường chủ tu, đọc kinh văn trong ngọc thạch thư và hấp thu bí chất của cổ trì. Ba đạo Tiên khí phân giải thành vô số sợi nhỏ rồi cắm rễ vào ngũ tạng, xương cốt và cốt tủy, khiến thân thể liên tục phá tổn rồi tái sinh. Quá trình ấy đưa Thạch Hạo tới giai đoạn tẩy tủy trong truyền thuyết và mở đầu một lần Đại Niết bàn ở tầng sâu."},{"chuong":1431,"tieuDe":"Thải Nhân Thể Đại Dược","tomTat":"Thạch Hạo trải qua nhiều đợt tẩy tủy cực đoan, khiến toàn bộ xương cốt đứt gãy, đào thải phần khô cạn rồi tái tạo bảo cốt bằng vật chất thần bí trong ao vàng. Hơn hai trăm khối xương của hắn hóa thành thần lô, lấy tiên vụ làm lửa để luyện cốt tủy thành thân thể đại dược có khả năng cải biến căn cơ. Khi đại dược chín muồi, toàn bộ cựu huyết bị đẩy khỏi cơ thể và bách cốt sinh ra thần huyết mới, đưa lần Đại niết bàn cấp độ sâu tới gần hoàn thành. Hắn chỉ còn cần tu dưỡng và bổ sung đủ thần năng để tiến vào một đại cảnh giới cao hơn. Trong Thần Dược sơn mạch, Kim Ngưu tiếp tục truy sát đội ngũ dị vực, đánh trọng thương một Đại tu sĩ Độn Nhất và giết nhiều sinh linh trẻ tuổi, còn Cổ thụ Thiết Huyết chặn những kẻ tìm đường tháo chạy. Dị vực vì thế đưa bí bảo cùng Hạc Tử Minh, Phản Tổ Giả Vô Úy Sư Tử, chí tôn trẻ tuổi Cô Tộc và một đại nhân trẻ tuổi Đế Tộc vào núi săn Hoang. Cùng lúc, Đế Quan bắt đầu điều tra nội gián liên hệ với dị vực và hướng sự nghi ngờ về những người trẻ tuổi chưa trở lại sau đại chiến biên hoang."},{"chuong":1432,"tieuDe":"Xuất Kích","tomTat":"Trong lòng đất Thần Dược sơn mạch, quá trình Đại niết bàn của Thạch Hạo gần hoàn tất, vết rách bản nguyên nhạt đi và chí tôn huyết tiến hóa nhờ thần bí vật chất trong ao vàng. Sau khi lấy một phần chất lỏng rồi rời địa quật, hắn vô tình chạm trán đại tu sĩ Độn Nhất dị vực đang trốn Kim Ngưu và bị đối phương truy sát. Thạch Hạo phá núi lửa để dẫn Kim Ngưu tới, dùng Đại La kiếm thai đỡ một chưởng rồi sống sót nhờ thể phách vừa được cường hóa, trong khi Kim Ngưu chuyển sang tiếp tục truy đuổi đại tu sĩ. Bắt đầu phản kích những kẻ vây quét mình, Thạch Hạo dùng Lôi Trì tiêu diệt tám tu sĩ trẻ dị vực cùng binh khí, sau đó giết một sư tử vàng không thuần huyết thuộc mạch Vô Úy Sư Tử. Ba sư tử vàng và một Phản Tổ Giả thuần huyết lần lượt tới kiểm tra chiến trường, khiến nguy cơ đối đầu với mạch Vô Úy Sư Tử tăng cao. Khi quay lại địa quật để chuẩn bị đột phá Trảm Ngã cảnh, Thạch Hạo phát hiện đại tu sĩ Độn Nhất dị vực đã chiếm ao vàng và tin rằng cơ duyên này có thể giúp mình trở thành Chí Tôn. Không để lộ hành tung, Thạch Hạo âm thầm rút lui và quyết định phải giết đối phương để đoạt lại mật địa đồng thời báo thù."},{"chuong":1433,"tieuDe":"Táng Sĩ","tomTat":"Thạch Hạo rời địa quật để tìm Kim Ngưu, dự định lợi dụng sinh linh này đối phó tu sĩ Độn Nhất cảnh đang truy lùng mình. Khi Bạch Hổ đằng xuất hiện, hắn dùng Thiên Nhãn nhận ra thần dược đã nhiễm tử khí và U Minh Chi Lực nên không tham gia tranh đoạt. Nhóm tu sĩ dị vực dùng lưới luyện từ ngôi sao sa truy bắt cây thuốc, vô tình phá vách núi và kéo một quan tài đồng mục nát lên khỏi địa mạch Cổ Táng khu. Táng sĩ mang cánh chim mục nát trong quan tài thức tỉnh, bộc lộ sức mạnh vượt Độn Nhất cảnh rồi truy sát những kẻ đã quấy nhiễu mình. Qua lời tu sĩ dị vực, Thạch Hạo biết Cổ Táng khu từng có một nền văn minh hùng mạnh, có quan hệ với khởi nguyên dị vực và từng xuất hiện táng sĩ tiêu diệt ba Đại Vương tộc trước khi giao chiến lâu dài với Du Đà. Hắn bắt một tu sĩ trẻ tuổi để ép khai báo thêm bí mật, nhưng táng sĩ nhanh chóng xuất hiện sau lưng. Thạch Hạo rút Đại La Kiếm Thai hộ thân, khiến sinh linh đáng sợ ấy bất ngờ run rẩy, quỳ xuống và dập đầu trước kiếm thai."},{"chuong":1434,"tieuDe":"Kiếm Thai Bí Mật","tomTat":"Thạch Hạo kinh ngạc khi táng sĩ cánh mục nát quỳ lạy Đại La kiếm thai, nhưng đối phương lập tức trở mặt tấn công người cầm kiếm và vô tình bóp nát tù binh dị vực. Không thể giao tiếp bằng cổ ngữ, táng sĩ dùng thần niệm mang U Minh Chi Lực để tra hỏi vì sao thanh kiếm nằm trong tay hắn. Thạch Hạo tránh để nguyên thần bị ăn mòn, đồng thời chống đỡ cuộc công kích dữ dội và bị dư lực làm ho ra máu. Dưới áp lực cùng tử khí của táng sĩ, Đại La kiếm thai lần đầu đồng thời chiếu hiện cảnh Phi Tiên và Cổ Táng Khu đẫm máu với một sinh linh ngồi trên quan tài đồng. Hình ảnh ấy khiến táng sĩ khiếp sợ liên tục lùi lại, qua đó cho thấy thanh kiếm có liên hệ sâu xa với táng thổ. Từ phát hiện này, Thạch Hạo nhận định Đại La kiếm thai cổ xưa và thần bí hơn mọi suy đoán trước đây, thậm chí có thể đã xuyên qua nhiều kỷ nguyên."},{"chuong":1435,"tieuDe":"Kéo Lên Đồng Nhất Chiến Xa","tomTat":"Táng sĩ nhận ra hình người ngồi trên quan tài đồng trong dị tượng của Đại La kiếm thai nên lập tức quỳ lạy và ngừng công kích Thạch Hạo. Qua cuộc trao đổi, Thạch Hạo biết kiếm đã lưu chuyển qua nhiều sinh linh, còn người nắm giữ chỉ là một trạm dịch mà nó sẽ rời bỏ khi trạm dịch mục nát; số phận bi thảm của các chủ nhân trước càng khiến hắn cảnh giác. Muốn tận dụng chiến lực của táng sĩ, Thạch Hạo gán cho An Lan và Du Đà nhiều hành vi xâm phạm Cổ Táng Khu, nhưng táng sĩ dùng nhãn thuật nhìn ra lời hắn thật giả lẫn lộn. Dù vậy, với lý do bảo vệ người đang giữ kiếm, táng sĩ vẫn đồng ý giúp hắn chiến đấu một lần trước khi trở về táng thổ. Thạch Hạo vì thế chuẩn bị chuyển từ bị săn sang phản săn toàn bộ cao thủ Dị vực đang kéo tới Thần Dược sơn mạch. Bên ngoài sơn mạch, người trẻ và tiền bối danh túc của nhiều đại tộc Dị vực đã tụ hội, trong đó có Cửu Mục Đạo Nhân đã tu thành Cửu nhãn thần thông."},{"chuong":1436,"tieuDe":"Khai Sát","tomTat":"Có táng sĩ đồng hành, Thạch Hạo chủ động săn giết những tu sĩ dị vực tiến vào Thần Dược Sơn Mạch. Hai người bắt gặp một đội dò đường gồm bảy tám tu sĩ trẻ tuổi, khiến họ hoảng sợ bỏ chạy rồi phối hợp tiêu diệt không còn ai sống sót. Không gặp được những mục tiêu lớn hơn, Thạch Hạo quay lại sào huyệt Kim Ngưu để báo thù đại tu sĩ Độn Nhất từng khiến mình trọng thương. Hắn dặn táng sĩ ẩn giấu khí cơ, cố ý kích hoạt pháp trận cảnh giới rồi giả vờ rút lui để dụ đối phương rời hồ vàng. Đại tu sĩ dùng tràng vực phong tỏa tám phương nhưng lập tức bị táng sĩ phục kích, nguyền rủa và ăn mòn đến mức huyết nhục thối rữa, không thể đào thoát. Táng sĩ vặn đứt đầu đối phương, còn Thạch Hạo dùng kiếm phá hủy Nguyên Thần, hoàn tất việc thanh toán nợ máu. Sau chiến thắng, Thạch Hạo tiếp tục ở lại sơn mạch, công khai chờ thêm quân dị vực tiến vào để lần lượt chôn vùi."},{"chuong":1437,"tieuDe":"Mẫu Căn","tomTat":"Thạch Hạo lấy thêm một đỉnh chất lỏng vàng rồi cùng táng sĩ rời khỏi khu vực của Kim Ngưu để tránh một cuộc giao chiến khó lường. Hắn chuyển sang tìm những đoạn Thiên Thần Thụ còn lại, mong hợp nhất bốn cây thành Thiên Tiên thụ có quả giúp người ăn thành chân tiên. Khi Thạch Hạo lấy cây màu vàng và vạn vật thổ ra dò tìm, táng sĩ nhận ra loại đất này là táng thổ quý báu, đồng thời khẳng định ngoại tộc không thể trở thành táng sĩ. Cây vàng cảm ứng được một đoạn mẫu căn gần đó và dẫn họ tới Thiên Thần Thụ màu đỏ thẫm có lá như chu tước. Cây đỏ phát hiện táng sĩ liền nhổ rễ bỏ chạy, điều động núi sông địa mạch để đạt tốc độ cực nhanh. Thạch Hạo truy đuổi tới nơi cây đỏ bị một đoàn sinh linh dị vực do hai ông lão lĩnh quân vây chặn. Đối phương nhận ra Hoang và tin rằng có Cửu Mục Đạo Nhân thì việc bắt hắn rất dễ dàng, nhưng Thạch Hạo đáp lại bằng lời tuyên bố sẽ chôn vùi toàn bộ lực lượng dị vực tới đây."},{"chuong":1438,"tieuDe":"Quần Sát","tomTat":"Cửu Mục đạo nhân, một cao thủ già của Vương tộc Dị Vực thành danh nhờ Cửu nhãn thần thông, tới Thần Dược Sơn Mạch tọa trấn và đối đầu Thạch Hạo. Thạch Hạo liên tục khiêu khích rồi giả vờ bỏ chạy nhằm gom các lực lượng Dị Vực vào phạm vi phục kích của Táng sĩ. Khi ông lão tóc vàng dùng Tụ lý càn khôn định bắt hắn, Táng sĩ bất ngờ phá thần thông, làm mục nát thân thể và cầm cố đối phương để Thạch Hạo tiêu diệt cả thân thể lẫn nguyên thần. Cửu Mục đạo nhân mở chín thần nhãn tìm đường thoát nhưng thần quang bị đôi cánh mục nát hóa giải, còn cổ thuật phong thiên tuyệt địa của Táng sĩ cầm cố toàn bộ sinh linh Dị Vực tại chiến trường. Thạch Hạo dùng Đại La kiếm thai giết Cửu Mục đạo nhân cùng các tu sĩ bị phong ấn, sau đó tiếp tục truy tìm Thiên Thần Thụ và tiêu diệt thêm nhiều toán địch trên đường. Bên ngoài dãy núi, lực lượng Dị Vực vẫn lầm tưởng Hoang đã bị bắt cho tới khi người báo tin chạy tới cho biết nhiều đội tiến vào núi đều đã chết."},{"chuong":1439,"tieuDe":"Đại Nguy Cơ","tomTat":"Các cường giả dị vực đang chờ kết quả truy sát Hoang thì nhận tin nhiều toán nhân mã, kể cả những cao thủ lâu năm, đã chết trong Thần Dược sơn mạch với thi thể mục nát và vết máu hóa đen. Lo ngại chôn sĩ xuất hiện và người trẻ tuổi Đế Tộc gặp nguy hiểm, Ba đầu Vương cùng đồng bọn quyết định dùng Bách kiếp thang trời tiến sâu vào núi, đồng thời báo động các Chí Tôn. Dị vực còn bố trí nhiều trận đài tại các tiết điểm trọng yếu, định dùng Thạch Hạo làm mồi nhử Mạnh Thiên Chính và những cường giả tối cao của Đế quan đến cứu rồi tiêu diệt một lượt. Kế hoạch này dựa trên tin do một sinh linh từ Đế quan vượt Biên Hoang sang dị vực cung cấp, bao gồm vị trí của Thạch Hạo và nhận định về phản ứng của Mạnh Thiên Chính. Khi biết nội bộ có kẻ tiết mật, Đế quan triệu tập khoảng mười vạn cường giả các tộc trong một tòa đồng điện để tự tra, nhưng sự nghi kỵ cũng nhanh chóng lan rộng. Một số người theo Vương gia và Kim gia nhân cơ hội vu cáo Thạch Hạo thông đồng với dị vực, song một thành viên Vương gia chín con rồng và con gái Kim thái quân trực tiếp bác bỏ, nhấn mạnh Hoang đã kết đại thù với các Vương Giả trẻ tuổi dị vực. Cuối cùng, một ông lão hiền hòa cho rằng Thạch Hạo tuy chưa đủ sức chi phối đại cục nhưng vẫn phải được cứu vì thiên tư và tiềm lực đặc biệt."},{"chuong":1440,"tieuDe":"Chí Tôn Sống Lại","tomTat":"Trong cuộc nghị sự tại Đế Quan, một lão giả Thiên Nhân tộc thừa nhận tộc mình từng có lỗi với Thạch Hạo nhưng chủ trương phải cứu hắn khỏi Thần Dược Sơn Mạch. Những cường tộc đi theo Vương gia tìm cách cản trở, song đệ ngũ Long bất ngờ quát phạt họ vì giở tâm cơ trước đại nghĩa. Mạnh Thiên Chính từ tổ đàn tới đồng điện, nhận Thạch Hạo là đệ tử và tuyên bố sẽ một mình lên đường cứu viện để tránh liên lụy thêm cường giả Đế Quan. Tào Vũ Sinh, Thái Âm Ngọc Thỏ và Trường Cung Diễn xông vào đồng điện phản đối những lời vu cáo Thạch Hạo; khi đệ ngũ Long dùng sóng âm công kích Tào Vũ Sinh, Kim gia bà lão ra tay bảo vệ hắn. Thái độ kính trọng của Mạnh Thiên Chính đối với sư tôn Tào Vũ Sinh khiến mọi người nhận ra người này có lai lịch và địa vị rất lớn. Trước lúc xuất phát, Mạnh Thiên Chính mở gông xiềng Chí Tôn huyết, khôi phục trạng thái đỉnh phong và khiến toàn Đế Quan rung chuyển. Thân thể già nua của ông tái tạo thành một nam tử trẻ tuổi khoác hoàng kim chiến y, tỏa ra thần uy khiến ngay cả những cường giả hàng đầu trong điện cũng gần như không chịu nổi."},{"chuong":1441,"tieuDe":"Mơ Ước Tiên Dược","tomTat":"Mạnh Thiên Chính xuất hiện trong hoàng kim chiến y với dáng vẻ trẻ trung và khí thế mạnh mẽ khác thường, khiến Đệ Ngũ Long cùng mọi người nghi ngờ ông vừa có biến chuyển lớn. Quá khứ ông từng suýt hình thần câu diệt trên con đường lấy thân là loại được nhắc lại, càng làm nổi bật sự trở về đỉnh cao nhân đạo hiện tại. Mạnh Thiên Chính sau đó rời đám đông, đi thẳng tới cửa thành và trận đài để xuất quan. Trong Thần Dược sơn mạch, Thạch Hạo cùng nữ táng sĩ tiến vào vùng sâu nhất, nơi bạch cốt phủ dày và biển thi thụ phát sáng bao quanh Thiên Thần Thụ màu đỏ thẫm. Nữ táng sĩ dùng cổ thần chú điều động thi thụ vây giữ cây đỏ, đồng thời giải thích chúng do bộ tộc mình gieo trên phần mộ để bảo vệ táng thổ. Khi nàng xác nhận Cổ Táng Khu có nhiều hơn một cây tiên dược, Thạch Hạo lập tức xin được dẫn đi tìm và đề nghị dùng vạn vật thổ trao đổi nhưng bị từ chối. Nữ táng sĩ còn kể từng thấy một đại nhân chém tiên thụ làm quan tài, khiến Thạch Hạo vừa kinh ngạc vừa tức nghẹn trước mức độ xa xỉ của những tồn tại sâu trong táng khu."},{"chuong":1442,"tieuDe":"Cấm Địa","tomTat":"Nữ Táng Sĩ kể cho Thạch Hạo những lời đồn kỳ dị về Chân Hoàng, táng thổ và Tiên thụ trong nơi sâu nhất của Cổ Táng Khu. Khi nàng vẽ tuyến đường tới ngoại vi táng khu, Thạch Hạo nhận ra đó chính là tuyệt địa được đánh dấu trên cổ đồ da thú của Đế quan và quyết định lên đường. Trước lúc rời đi, hắn cùng Nữ Táng Sĩ hộ pháp để hai Thiên Thần thụ dung hợp bản nguyên, tạo thành thân cây mang hai màu đỏ vàng rồi cắm rễ vào vạn vật thổ. Thạch Hạo sau đó bắt tù binh và xác nhận dị vực đã bố trí Chí Tôn cùng tuyệt thế đại trận ngoài Thần Dược Sơn Mạch để phục kích lực lượng cứu viện. Nữ Táng Sĩ điều động hài cốt ngoài đại mạc ghép thành chữ, giúp hắn báo bình an và cảnh báo Đế quan không tiến vào bẫy. Khi một nhóm tu sĩ dị vực mang Bách Kiếp Thang Trời vào núi, Thạch Hạo tránh giao chiến và để họ tự đối phó với các đại hung. Nữ Táng Sĩ dẫn hắn xuống táng mạch, dùng chiến xa rỉ sắt vượt qua khoảng cách cực xa tới một vùng địa mạch đầy quan tài đá. Tại vùng cấm tĩnh lặng, Thạch Hạo thấy máu thịt mình hóa thành ánh sáng và chỉ còn bộ xương khô, còn Nữ Táng Sĩ hiện ra như một thiếu nữ có đôi cánh trắng rồi khẳng định bản thân vẫn sống."},{"chuong":1443,"tieuDe":"Táng Vực Thánh Địa","tomTat":"Thạch Hạo kinh hãi phát hiện toàn bộ huyết nhục đã biến mất, chỉ còn bộ xương trắng, dù Nguyên Thần của hắn vẫn nguyên vẹn. Nữ Táng Sĩ đưa gương đồng cho hắn kiểm tra rồi kể truyền thuyết về một Táng Vương đã chết nhưng huyết nhục hóa thành bướm và cuối cùng trở lại mộ nhìn thấy hài cốt của chính mình. Nàng suy đoán Thạch Hạo còn đáng sợ hơn, có thể là chấp niệm không diệt của một tồn tại vô thượng đã chết từ vô số năm trước, nhưng hắn kiên quyết không chấp nhận cách giải thích này. Sự xuất hiện của Thạch Hạo khiến Táng Vực Thánh địa đang hoang phế bất ngờ thức tỉnh, mặt đất nứt vỡ và hàng loạt bia đá cổ mang đại đạo khí tức trồi lên tận tầng mây. Tiếp đó, đường chân trời bị xé mở, dòng sông thời gian cùng sương mù hỗn độn hiện ra trong một trận thiên biến. Từ phía bên kia, một người bí ẩn đau đớn gọi Hoang là huynh đệ và Thiên Đế, nói đã tìm kiếm hắn suốt một kỷ nguyên, từng tự táng chín đời và truy tìm dấu vết của hắn trên Tiên lộ lẫn trong luân hồi. Xác nhận tiếng gọi không phải ảo giác, Thạch Hạo tiến về phía chân trời tìm người đang khóc, còn Nữ Táng Sĩ căng thẳng đi theo."},{"chuong":1444,"tieuDe":"Vạn Cổ Một Góc","tomTat":"Thạch Hạo nhìn qua dòng sông thời gian và thấy một đạo sĩ béo mặc bảo y Tiên kim rách nát đang khóc tang Hoang, đồng thời tuyên bố sẽ đào khắp tuyệt địa và cổ mộ để tìm người bạn cũ. Trong cuộc trò chuyện với đệ tử, đạo sĩ hé lộ rằng những truyền thuyết kinh người về các kỷ nguyên xa xưa chỉ là một góc nhỏ của thời đại hắc ám, còn ý chí của ông đã chinh chiến qua nhiều đời Luân Hồi. Khi cường địch kéo tới, hai thầy trò rút khỏi vòng vây và dự định đánh vào mộ tổ đối phương. Nhận ra đạo sĩ rất giống Tào Vũ Sinh, Thạch Hạo gọi tên người bạn xuyên qua Cổ Hà, khiến đạo sĩ nghe thấy tên kiếp trước và quay lại nhìn sang thời đại của anh. Đúng lúc hai bên tương kiến, huyết nhục tái sinh trên bộ xương Thạch Hạo và đạo sĩ xúc động nhận ra Hoang vẫn còn sống. Tuy nhiên, khi Tào Vũ Sinh định tiết lộ chuyện tương lai, Tiên đạo lôi đình lập tức giáng xuống; Nữ Táng Sĩ giải thích rằng cuộc đối thoại đã chạm tới đại sự có thể ảnh hưởng thiên cổ và dòng sông năm tháng nên bị trời đất ngăn cản."},{"chuong":1445,"tieuDe":"Ôn Chuyện","tomTat":"Sau khi lời nói quan trọng của Tào Vũ Sinh bị thiên uy che lấp, Thạch Hạo suy ngẫm về chín đời chôn cất và lo rằng cố nhân đã không còn là chính mình. Tào Vũ Sinh khẳng định chín đạo Luân Hồi dấu ấn giúp hắn nhớ lại toàn bộ quá khứ, rồi xúc động hồi tưởng những người bạn và thời đại đã bị năm tháng mai táng. Hắn cho biết hậu thế chỉ còn truyền tụng tên Hoang, trong khi bản thân từng đi khắp các vực nhưng vẫn không tìm thấy Thạch Hạo. Khi Thạch Hạo hỏi về số phận những cố nhân, một người bí ẩn chủ động gánh thiên uy, còn Tào Vũ Sinh vẫn bị lôi đình xuyên thủng và đánh tan thân thể vì cố tiết lộ tương lai. Tào Vũ Sinh báo rằng những người quen đã đi cùng Thạch Hạo, sau đó dùng Độ kiếp tiên công gây dựng lại cơ thể và sống sót. Cuối cùng, hắn quyết định nói ra một chuyện cực kỳ trọng đại dù có thể phải chịu thiên phạt hoặc mất mạng, nhưng nội dung chưa kịp được tiết lộ."},{"chuong":1446,"tieuDe":"Gặp Lại Vô Hạn","tomTat":"Ở bờ bên kia năm tháng Cổ Hà, Tào Vũ Sinh liều mạng chống Tiên Đạo lôi đình để cảnh báo Thạch Hạo về một bí mật ảnh hưởng sâu xa đến cổ kim. Thiên uy cắt đứt tiếng nói và thần niệm, khiến hắn chỉ truyền được hai phần rời rạc là “Cẩn thận” và “Điện” trước khi bị đánh nát thành mưa máu. Tào Vũ Sinh sau đó tái tạo thân thể và thoát chết trong tình trạng trọng thương, đồng thời giải thích rằng mọi nỗ lực thay đổi thời gian đều có thể khiến bản thân bị trời đất xóa bỏ mà thông tin vẫn không tới đích. Vì chưa biết chân tướng hậu thế, hắn quyết định tìm người liên thủ điều tra và cho biết thời đại của mình đã xuất hiện dấu hiệu đại kiếp. Nhớ lại những người xưa, Tào Vũ Sinh nhờ Thạch Hạo bảo vệ Thái Âm Ngọc Thỏ và kể về một Yêu Hoàng hình thỏ vô địch ở đời sau mà hắn nghi có liên hệ với nàng. Hắn còn kéo người đệ tử đầu trọc đang nghe lén tới trước Môn, dùng đại pháp lực để người này và Thạch Hạo nhìn thấy nhau qua hai thời đại. Sau lời hứa bảo vệ mọi người và lời từ biệt của Thạch Hạo, năm tháng Cổ Hà biến mất, khiến Tào Vũ Sinh cùng đệ tử hoàn toàn khuất khỏi tầm mắt."},{"chuong":1447,"tieuDe":"Tế Tự","tomTat":"Sau khi cảnh tượng kỳ dị chấm dứt, huyết nhục vừa tái sinh của Thạch Hạo lại biến mất, khiến hắn trở về trạng thái bộ xương trắng. Nữ Táng Sĩ cho rằng chấp niệm của hắn quá sâu, nhưng Thạch Hạo kiên quyết phủ nhận mình đã chết hoặc là sản phẩm do chấp niệm của một tồn tại khác tạo thành. Khi tiến sâu vào Cổ Táng Khu, hai người chứng kiến một trong Tam đại tế tự Thánh địa hiện lên với cự bi, cổ điện và những lăng mộ lớn. Nữ Táng Sĩ tiết lộ Táng Sĩ là chủng tộc trời sinh tại Táng Vực, có cha mẹ và khả năng sinh nở, chứ không phải thi thể phát sinh biến đổi. Lần theo một mùi hương lạ, họ tìm tới đạo đài cổ nơi Tử Phủ dịch và địa tủy chảy ra từ các vết nứt. Tại mặt sau đạo đài, hai người phát hiện Trường Sinh Thụ tối cổ đang tái sinh từ gốc từng bị chặt, tỏa ngũ sắc tiên quang và có khả năng trợ giúp Táng Sĩ ngộ đạo. Biết một Táng Vương vô thượng từng muốn dùng thân cây làm quan tài nhưng không nỡ, Thạch Hạo càng tiếc nuối trước dấu vết cây đã bị chặt."},{"chuong":1448,"tieuDe":"Tiên Thụ Khiêu Khích","tomTat":"Thạch Hạo quan sát Trường Sinh Thụ và nhận ra hương thơm của nó tác động trực tiếp đến nguyên thần, cho thấy cây thuốc có thể giúp cả linh hồn lẫn thân thể lột xác. Nữ Táng Sĩ suy đoán việc tiên dược chạy khỏi nơi sâu trong Táng Vực là dấu hiệu chiến tranh sắp làm khu vực này đại loạn, đồng thời tiết lộ ngay cả táng sĩ cũng không biết hết các tầng mộ và cường giả dưới lòng đất. Bất chấp cảnh báo, Thạch Hạo dùng bảo cụ cùng trận văn phong tỏa thiên địa để bắt cây thuốc, nhưng nó kịp trốn vào Đạo thai tàn tạ. Đạo thai thông linh đánh văng bảo cụ, làm nứt hổ khẩu Thạch Hạo và hiện một khuôn mặt lạnh lùng, buộc hai người phải rút lui. Trường Sinh Thụ sau đó xuyên phá cấm chế, trồi lên mặt đất rồi dùng rễ chạy và lấy cành khiêu khích những người truy bắt. Thạch Hạo cùng Nữ Táng Sĩ đuổi theo nhưng dần nhận ra cây thuốc đang cố tình dẫn họ về một hướng đặc biệt. Cuộc truy đuổi đưa họ đến gần ranh giới rời khỏi cổ táng địa Thánh địa, trong khi mục đích thật sự của Trường Sinh Thụ vẫn chưa rõ."},{"chuong":1449,"tieuDe":"Làm Khó Dễ","tomTat":"Rời khỏi khu vực Thánh địa hoang phế, Nữ Táng Sĩ bị ách thổ khiến âm khí sôi trào nên phải quay lại đạo đài cổ, còn Thạch Hạo tiếp tục truy tìm Trường Sinh Thụ. Hắn giả vờ suy yếu để nhử Tiên dược nhưng cây thuốc vẫn cảnh giác và không xuất hiện trở lại. Những hoa văn đầu lâu bằng đất đen giúp Thạch Hạo đối chiếu với cổ đồ da thú tại Đế Quan và xác định ách thổ chính là vùng tạo hóa giữa Thần Dược Sơn Mạch, Thiên Thú Sâm Lâm và cổ táng khu. Ba cao thủ Vô Úy Sư Tử tiến vào đây rồi tiết lộ đại nhân trẻ tuổi Đế tộc đã mang chí bảo đi trước, trong khi người của Cô tộc cũng nhắm tới cơ duyên này. Khi chúng bàn cách trừ khử Hoang và nhắc đến phản Tổ giả của tộc mình, Thạch Hạo bất ngờ tập kích, đánh trọng thương rồi bắt sống một con Trảm Ngã cảnh. Trước lời yêu cầu dừng tay của hai con còn lại, hắn lập tức chém một chân tù binh để ép chúng khai ra bí mật của ách thổ."},{"chuong":1450,"tieuDe":"Du Đà Ghi Nhớ","tomTat":"Thạch Hạo áp chế ba Hoàng Kim sư tử và ép chúng khai ra rằng Du Đà từng đào được một bộ sách cổ tàn khuyết trong Cổ Táng Khu, bên trong ghi địa điểm thần bí chôn giấu một tạo hóa chưa rõ bản chất. Những lời đồn xoay quanh kinh thư chí cao, táng khí khắc chế Táng Sĩ, sức mạnh vô địch hoặc một đạo thể vô song, đồng thời hé lộ Du Đà và An Lan đã nhiều lần phái người thăm dò nhưng đều thất bại. Con sư tử bị bắt bí mật phá phong ấn rồi cùng hai đồng bạn thi triển Vô Úy Sư Tử hống đánh lén, song Thạch Hạo nhanh chóng hóa giải. Ba con sư tử tiếp tục dùng bình bát và Hàng Ma Xử rạn nứt của cổ tăng, nhưng kiếm thai cùng quyền lực của Thạch Hạo lần lượt phá hủy cả hai cổ bảo. Thạch Hạo sau đó chém giết cả ba đối thủ rồi tiến sâu hơn vào cổ địa. Khi một làn sóng năng lượng màu đen tràn ra từ nơi sâu nhất, hắn lập tức tháo chạy và nhìn thấy ba cao thủ dạng khung xương gồm một hình người, một sư tử màu vàng cùng một sinh linh Cô Tộc điều khiển lực lượng thời gian và không gian cũng đang chạy trốn."},{"chuong":1451,"tieuDe":"Xuất Thế","tomTat":"Biển năng lượng màu đen hóa thành sóng lớn truy đuổi Thạch Hạo cùng ba cao thủ, đồng thời phong cấm hư không và áp chế khả năng phi hành cũng như nhiều thần thông trong ách thổ. Khi Thạch Hạo thử đánh thần quang vào biển đen, nguồn lực này phản kích dữ dội và làm gãy một đoạn xương đuôi của Phản Tổ Giả Vô Úy Sư Tử; đại nhân trẻ tuổi Đế Tộc cảnh báo rằng nó càng bị công kích mạnh thì càng trở nên mạnh hơn. Nhờ đang mang hình thái khô lâu và che giấu khí cơ chân thân, Thạch Hạo quyết định tạm giả làm tu sĩ Dị Vực để chờ cơ hội tập kích ba cao thủ. Trường Sinh Thụ cũng bị ép lộ diện và chạy trên mặt đất, khiến cả nhóm đổi hướng truy đuổi. Khi bị áp sát, cây già chủ động rụng một chiếc Tiên diệp chứa sinh cơ Tiên đạo để làm Thạch Hạo phân tâm, nhờ đó tiến vào thánh địa và chui xuống lòng đất. Biển đen bị một lực vô hình chặn ngoài thánh địa, còn từ nơi sâu trong đó dựng lên một chùm sáng thần thánh và nhu hòa. Chí tôn trẻ tuổi Cô Tộc xác nhận nơi cần mở đã được mở và vật được Du Đà cùng An Lan ghi nhớ đã xuất thế."},{"chuong":1452,"tieuDe":"Trong Mộ Vật","tomTat":"Giữa đại dương năng lượng màu đen, một ngôi mộ lớn màu đỏ sậm trồi lên và nứt vỡ, để lộ chiếc rương gỗ cổ tỏa ánh sáng vàng kim thần thánh. Đoàn dị vực xác nhận đây là mục tiêu mà Du Đà, An Lan cùng các Bất Hủ chi Vương đã hao tổn nhiều bí khí, trận kỳ và Tiên kim để tìm kiếm. Đại nhân trẻ tuổi Đế Tộc, Chí tôn trẻ tuổi Cô Tộc và Hoàng Kim sư tử lần lượt thả hai mươi lăm lão binh Cửu Thiên Thập Địa đã bị luyện thành con rối, ép họ tiến xuống biển lấy rương. Bí lực màu đen nhanh chóng nghiền nát toàn bộ các lão binh, kể cả năm người được gọi là binh vương, khiến họ hình thần câu diệt. Thạch Hạo phẫn nộ trước số phận của những chiến binh cổ nhưng chưa thể ra tay, đồng thời không tìm thấy Nữ Táng Sĩ để hỏi về biến động. Khi cách dùng con rối thất bại, Đại nhân trẻ tuổi Đế Tộc trang nghiêm thỉnh Du Đà và An Lan giáng lâm trực tiếp ra tay, khiến Thạch Hạo kinh hãi trước khả năng Bất Hủ chi Vương can thiệp vượt qua Thiên Uyên."},{"chuong":1453,"tieuDe":"Bất Hủ Chi Vương Giáng Lâm","tomTat":"Đại nhân trẻ tuổi Đế Tộc ngâm tụng đầy đủ chân danh của Du Đà và An Lan, nhưng hình bóng mơ hồ được gọi tới nhanh chóng tan biến vì sự hạn chế của Thiên Uyên. Không chấp nhận thất bại, hắn dựng một cốt đài xương tím, bố trí trận kỳ và hợp lực cùng Cô Tộc truyền nhân, Vô Úy Sư Tử đưa pháp đài vào biển năng lượng màu đen. Cốt đài nứt ra để lộ Du Đà chân huyết, còn tấm da thú ghi triệu hoán kinh thấm máu rồi tự cháy, phát ra tiếng tụng đầy đủ danh hiệu Du Đà. Nghi thức xé rách bầu trời, mở một cánh cửa xuyên Thiên Uyên và dẫn pháp thể mạnh nhất của Du Đà giáng lâm. Bàn tay khổng lồ của Du Đà tiến vào biển năng lượng, khiến đại tinh rơi rụng và biển sao trút xuống, nhưng sức mạnh của Táng khu Thánh địa bảo vệ những người đang có mặt. Khi bàn tay ấy sắp chạm tới rương gỗ vỡ mà Du Đà đã mưu cầu suốt nhiều vạn năm, một khí tức khủng bố từ Cổ táng địa truyền đến. Một sinh linh chưa rõ thân phận trong quốc gia táng địa bắt đầu thức tỉnh, báo hiệu cuộc đối đầu mới có thể xảy ra."},{"chuong":1454,"tieuDe":"Cự Đầu Giao Thủ","tomTat":"Biến động quanh ngôi mộ lớn đỏ sậm và Nát rương gỗ truyền theo chi mạch táng khu, đánh thức một Táng sĩ trong cổ mộ gần Cổ Táng Địa. Du Đà dùng bàn tay pháp thể vượt giới, liên tiếp phá qua kiếm khí xích hà, sương đỏ và sức mạnh từ phế tích để đoạt chiếc rương. Những hậu bối Dị Vực suy đoán ngôi mộ từng chôn một tồn tại vô thượng, còn thi thể cũ đã bị đào đi để nhường chỗ cho vật thần bí này. Khi Du Đà mang rương rút lui, một bàn tay trắng bệch khổng lồ vượt khoảng cách xa xôi, phá trường vực và liên tục chặn đánh hắn. Thạch Hạo quan sát từ nơi được Thánh địa che chở, đồng thời quyết định sẽ tìm cơ hội giết Vô Úy Sư Tử vì sự phản bội và thái độ sùng kính Dị Vực của nó. Trước lúc pháp thể Du Đà hết thời hạn, Cốt đài triệu hoán đốt cháy cổ huyết, tái hiện uy thế Hoàng Kim trường thương để bàn tay An Lan đâm xuyên và ghim bàn tay Táng sĩ giữa hư không."},{"chuong":1455,"tieuDe":"Táng Vương","tomTat":"An Lan hiện thân bằng một bàn tay pháp thể, dùng hoàng kim trường thương đâm xuyên bàn tay trắng bệch vươn ra từ táng địa. Một Táng Vương cổ xưa sau đó xuất hiện, phá hủy pháp đài xương tím đang duy trì pháp thể Du Đà, khiến nát rương gỗ rơi xuống biển năng lượng màu đen. Táng Vương kết pháp ấn đối đầu An Lan giữa dòng sông năm tháng, đồng thời bị dấu ấn thời gian của Du Đà bất ngờ đánh trúng. Khi thời gian hiện diện kết thúc, An Lan cùng hoàng kim trường thương hoàn toàn biến mất, còn Thiên Uyên chấn động và chấn nhiếp toàn bộ chiến trường. Táng Vương không lấy chiếc rương mà quay về mộ lớn trong chi mạch cổ táng địa tại Biên Hoang. Sau khi các cường giả rút đi, biển năng lượng màu đen thoái sâu vào ách thổ, để nát rương gỗ trở thành vật vô chủ tại chỗ."},{"chuong":1456,"tieuDe":"Va Chạm","tomTat":"Sau khi Táng Vương, Du Đà và An Lan rời ách thổ, Nát rương gỗ vẫn nằm trên nền đất đỏ sậm và tạm thời trở thành vật vô chủ. Đại nhân trẻ tuổi Đế Tộc, Chí tôn trẻ tuổi Cô Tộc và Vô Úy Sư Tử giả vờ mời bộ xương hình người tới giúp lấy rương, trong khi Thạch Hạo cũng định áp sát để tập kích họ. Hai phía gần như đồng thời ra tay, khiến kế hoạch ám sát biến thành một cuộc va chạm trực diện. Hắc thạch trụy của Đại nhân trẻ tuổi Đế Tộc trung hòa pháp lực miễn dịch, còn Vô Úy Sư Tử dựa vào tuyệt học vừa bộc lộ và lời đối đáp để nhận ra bộ xương chính là Hoang. Thạch Hạo giữ địa thế thuận lợi, không để ba đối thủ vây kín, rồi chủ động dùng thần quang đánh thử Nát rương gỗ. Khi chiếc rương chỉ bay ngang mà không phát uy hoặc dẫn tới dị biến, cả bốn người lập tức gác việc săn giết sang một bên và đồng loạt lao tới tranh đoạt báu vật."},{"chuong":1457,"tieuDe":"Tiên Dược Điên Cuồng Hơn","tomTat":"Thạch Hạo cùng Vô Úy Sư Tử, truyền nhân Cô Tộc và cao thủ trẻ tuổi Đế Tộc tranh đoạt nát rương gỗ, trong khi ba người dị vực vừa hợp tác vừa ngăn cản lẫn nhau vì đều muốn chiếm vật này trước. Vô Úy Sư Tử thi triển Sư Tử Hống và gọi dấu ấn cổ tổ, truyền nhân Cô Tộc sử dụng song mâu thời gian và không gian, còn cao thủ Đế Tộc tung trường đao có đao khí bao trùm cương vực. Thạch Hạo dùng Lục Đạo Luân Hồi, Đại La kiếm thai và Bất Diệt Kinh để chống đỡ rồi phá khỏi vòng vây. Khi ba cao thủ dị vực thống nhất ưu tiên giết Thạch Hạo, nát rương gỗ bất ngờ bị Trường Sinh Tiên thụ âm thầm nâng lên và cuốn đi. Truyền nhân Cô Tộc dùng Không gian chi mâu ép tiên dược hiện khỏi hư không, nhưng nó lập tức chui xuống tầng đất có khả năng ngăn cách cảm giác. Nhờ chiếc lá còn lưu khí tức của Trường Sinh Tiên thụ, Thạch Hạo khóa chặt tung tích và tiếp tục truy đuổi dưới lòng đất, kéo theo ba cao thủ dị vực bám sát phía sau."},{"chuong":1458,"tieuDe":"Ngộ Vào Địa Phủ","tomTat":"Thạch Hạo tức giận đuổi theo Trường Sinh thụ đang ôm hòm gỗ mục bỏ chạy, nhưng độn thuật của tiên dược khiến hắn khó bắt kịp. Ba cường giả trẻ tuổi dị vực đánh xuyên đại địa để tranh đoạt mục tiêu, trong đó truyền nhân Cô Tộc dùng Hư không liên y xác định lại phương vị tiên dược. Thạch Hạo dùng lôi đình mang dấu ấn Lôi Trì phản kích, rồi cùng các đối thủ tái sinh máu thịt sau khi rời xa Thánh địa và ách thổ, qua đó xác nhận dị biến trước đó do đất cổ gây nên. Vô Úy Sư Tử thi triển Chưởng Trung Tăng Quốc và truyền nhân Cô Tộc phóng trường mâu tập kích, nhưng Thạch Hạo dùng Đại La kiếm thai phá cả hai đòn rồi tiếp tục truy đuổi. Hắn theo Trường Sinh thụ xông vào chi mạch táng địa, tránh bàn tay từ quan tài hóa đá nhưng đánh thức một Táng Sĩ mạnh hơn và bị sinh linh này truy sát. Những vách đá kỳ dị buộc tiên dược cùng Thạch Hạo tiến sâu vào một cổ địa dưới lòng đất, nơi có đông đảo Táng Sĩ đang mua bán và trao đổi vật phẩm. Giữa phố chợ ấy, Thạch Hạo nhận ra những sinh linh không mang tử khí chính là Hoàng Kim Táng Sĩ."},{"chuong":1459,"tieuDe":"Chân Thành Hợp Tác","tomTat":"Thạch Hạo và Trường Sinh Thụ vô tình tiến vào một khu tụ cư đông táng sĩ, trong khi lối vào bị một táng sĩ ba đầu sáu tay có tu vi ít nhất Độn Nhất trấn giữ. Không thể rút lui trực tiếp, Thạch Hạo tiến sâu vào gò đất và quyết định giả mạo hoàng kim táng sĩ, buộc cây thuốc thu nhỏ rồi đậu trên vai mình để phối hợp che giấu thân phận. Trường Sinh Thụ dùng cổ táng ngữ ứng phó với những người xung quanh và dạy Thạch Hạo từng câu để hắn trò chuyện mà không lộ sơ hở. Một hoàng kim táng sĩ tóc vàng đạt Độn Nhất cảnh đỉnh cao chủ động bắt chuyện, cho rằng Thạch Hạo mang Trường Sinh dược tới tham dự chuyến đi táng uyên. Qua cuộc đối thoại, Thạch Hạo biết vực sâu màu đen này sắp mở và đang thu hút hàng chục hoàng kim táng sĩ tới tìm thiên tài địa bảo cùng bia đá tâm kinh. Trường Sinh Thụ chỉ chịu tiết lộ thêm sau khi yêu cầu được tự do rời đi, còn Thạch Hạo đồng ý vì mục tiêu của hắn vốn là thoát khỏi táng thổ. Hai bên vì thế tạm gác sự nghi kỵ và chính thức đạt thành thỏa thuận hợp tác."},{"chuong":1460,"tieuDe":"Hoàng Kim Táng Sĩ","tomTat":"Tại phố chợ gần Táng Uyên, Thạch Hạo nhận ra Táng Sĩ không chỉ quanh năm trầm miên mà còn tập hợp để trao đổi vật liệu, cổ khí và chuẩn bị cho những lần vực sâu mở cửa. Hoàng Kim Táng Sĩ Tam Tạng báo rằng Táng Uyên có thể mở ngay trong ngày, rồi giới thiệu Thạch Hạo dưới tên Hoang với nữ Hoàng Kim Táng Sĩ Thần Minh. Thần Minh nhận ra hắn mang theo Trường Sinh dược và cho biết nhóm nàng cũng chỉ có một cây tử dược hình người màu tím, được chín tầng thần hoàn bao quanh. Trường Sinh thụ giải thích rằng tiên dược có thể dẫn tới thiên trân và táng bảo trong Táng Uyên nhưng cũng sẽ chịu ảnh hưởng lớn, đồng thời suy đoán tử dược kia thuộc về cự phách dưỡng kê sâu trong Cổ Táng Vực. Khi xem xét các món đồ trong phố chợ, Thạch Hạo biết khối máu khô từng rơi ra từ một đại nhân vật vô thượng, còn tấm ván quan tài mục nát vốn là bộ phận của Trường Sinh thụ. Nhận ra những vật tưởng như phế phẩm có thể là táng bảo quý hiếm, hắn quyết định đổi lấy một số món để mang ra ngoại giới trước khi đoàn người lên đường."}];
